// El canary manda el evento en el body. Todo lo que viene de la peticion (uri, ua, referer, host)
// lo controla quien toco el senuelo: aqui solo se normaliza y se recorta; el escape va al componer.
const e = $json.body ?? $json;
const txt = (v, n) => { const s = v === undefined || v === null ? '' : String(v); return s.length > n ? s.slice(0, n) + '…' : s; };

return [{
  json: {
    ts: txt(e.ts, 40),
    origen: txt(e.origen, 40),
    severidad: e.severidad === 'critico' ? 'critico' : 'informativo',
    host: txt(e.host, 120),
    metodo: txt(e.metodo, 12),
    uri: txt(e.uri, 400),
    uri_recortada: String(e.uri ?? '').length > 400,
    ip: txt(e.ip, 64),
    pais: txt(e.pais, 8),
    ua: txt(e.ua, 300),
    referer: txt(e.referer, 300),
    cf_ray: txt(e.cf_ray, 40),
    // Solo false explicito cuenta como "directo": un evento antiguo sin el campo no debe alarmar.
    via_cloudflare: e.via_cloudflare === true ? true : (e.via_cloudflare === false ? false : null),
    cabecera_falsificada: e.cabecera_falsificada ? txt(e.cabecera_falsificada, 64) : null,
  }
}];

const c = $('Clasificar').first().json;

// Telegram interpreta HTML: todo valor del evento se escapa. Ademas autoenlaza dominios, IPs, URLs y
// correos en texto plano aunque haya parse_mode, asi que lo que no va en <code> lleva un word joiner
// (U+2060) tras cada punto, :// y @. Sin esto, un User-Agent con un "<" suelto hacia fallar la alerta
// y uno con <a href> dejaba un enlace clicable dentro del canal de alertas.
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const plano = v => esc(String(v ?? '').replace(/([A-Za-z0-9-])\.(?=[A-Za-z0-9-])/g, '$1.⁠').replace(/:\/\//g, ':⁠//').replace(/@/g, '@⁠'));
const vacio = v => v === null || v === undefined || v === '' || v === '-';

// Los enriquecimientos van con onError=continue: prefiero una alerta pobre a ninguna.
let abuse = {};
let gn = {};
try { abuse = $('AbuseIPDB').first().json?.data ?? {}; } catch (err) {}
try { gn = $('GreyNoise').first().json ?? {}; } catch (err) {}

const score = Number.isFinite(Number(abuse.abuseConfidenceScore)) && abuse.abuseConfidenceScore !== null ? Number(abuse.abuseConfidenceScore) + '/100' : 'n/d';
const pais = abuse.countryCode || (vacio(c.pais) ? 'n/d' : c.pais);
const clase = gn.classification ?? 'n/d';

const wpress = c.severidad === 'critico';
const falsa = !vacio(c.cabecera_falsificada);
const directo = c.via_cloudflare === false;
const dirigido = wpress || falsa || directo;

let titulo;
let explicacion;
if (wpress) {
  titulo = '\u{1F6A8} <b>CANARY CRÍTICO — acceso dirigido</b>';
  explicacion = 'Ese nombre lleva sufijo aleatorio: no se adivina por fuerza bruta. Alguien capturó la URL mientras el archivo estuvo expuesto. Revisar ya.';
} else if (falsa) {
  titulo = '\u{1F6A8} <b>CANARY CRÍTICO — cabecera de Cloudflare falsificada</b>';
  explicacion = 'Le habló directo al servidor fingiendo venir de Cloudflare, con CF-Connecting-IP <code>' + esc(c.cabecera_falsificada) + '</code>. Conoce la IP real del origen e intenta que se registre otra IP. Revisar ya.';
} else if (directo) {
  titulo = '\u{1F6A8} <b>CANARY CRÍTICO — directo al origen</b>';
  explicacion = 'La petición no pasó por Cloudflare: quien la hizo conoce la IP real del servidor. Revisar de dónde la sacó (registros DNS antiguos, certificados emitidos, cabeceras de correos salientes).';
} else {
  titulo = '\u{1F440} <b>Canary — sondeo de escáner</b>';
  explicacion = 'Nombre genérico de respaldo. Casi seguro escaneo masivo automatizado, sin acción inmediata.';
}

const hora = (() => {
  const d = new Date(c.ts);
  if (isNaN(d)) return null;
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: 'America/Santiago', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(d).map(x => [x.type, x.value]));
  return p.day + '-' + p.month + '-' + p.year + ' ' + p.hour + ':' + p.minute + ':' + p.second;
})();

const L = [titulo, ''];
L.push('<b>URI:</b> <code>' + esc((vacio(c.metodo) ? '' : c.metodo + ' ') + c.uri) + '</code>' + (c.uri_recortada ? ' (recortada)' : ''));
if (!vacio(c.host)) L.push('<b>Host:</b> <code>' + esc(c.host) + '</code>');
L.push('<b>IP:</b> <code>' + esc(c.ip) + '</code> (' + plano(pais) + ')');
L.push('<b>Cloudflare:</b> ' + (c.via_cloudflare === true ? 'sí' : c.via_cloudflare === false ? '<b>NO, directo al origen</b>' : 'n/d'));
L.push('<b>AbuseIPDB:</b> ' + score);
L.push('<b>GreyNoise:</b> ' + plano(clase) + (gn.name ? ' — ' + plano(String(gn.name).slice(0, 80)) : ''));
L.push('<b>User-Agent:</b> ' + plano(c.ua));
if (!vacio(c.referer)) L.push('<b>Referer:</b> <code>' + esc(c.referer) + '</code>');
if (!vacio(c.cf_ray)) L.push('<b>CF-Ray:</b> <code>' + esc(c.cf_ray) + '</code>');
L.push('<b>Hora:</b> ' + (hora ? hora + ' (Chile)' : plano(c.ts)));
L.push('', explicacion);

return [{ json: { ...c, abuse_score: score, greynoise: clase, dirigido, mensaje: L.join('\n') } }];
